// Quizzes for the "Make a Leather Strap" track, layered on by enrich.js.
// Every question comes from the lesson's own text. Numbers a lesson gives as
// measured, estimated or one maker's are tested as a decision, not a hard fact.
// sm-overview and sm-stitch keep the quizzes they already carry in strapmaking/.

export const QUIZZES = {
  'sm-leather': [
    { q: 'You are placing strap templates on a side of veg-tan. Where do they go?', options: ['Across the belly, where the leather bends most easily', 'Across the flanks, so the grain runs round the wrist', 'Along the backbone, in the shoulder or butt', 'Along the belly edge, where the hide is widest'], answer: 2, explain: 'Fibres are tightest and stretch least along the backbone in the shoulder and butt. Belly and flanks are loose, and a strap cut across the grain stretches within weeks.' },
    { q: 'You have split a firm top to 1.7 mm. Which lining goes under it?', options: ['0.5 mm', '1 mm', '1.5 mm', '2 mm'], answer: 0, explain: 'The rule links the two: a 0.5 mm lining under a 1.5–2 mm top, a 1 mm lining under a thinner top. That keeps the stack inside the thickness budget.' },
    { q: 'A customer wants a burnished edge. Which stack can deliver it?', options: ['Firm veg-tan top, Haas Zermatt lining', 'Horween Chromexcel top, veg-tan lining', 'Goat top, chrome-tanned calf lining', 'Firm veg-tan top, veg-tan lining'], answer: 3, explain: 'A burnished edge needs veg-tan on both layers. Zermatt is chrome-tanned, so it forces a painted edge, and Chromexcel is a pull-up leather that will not burnish.' },
    { q: 'You want a padded strap with a crisp, carved dome. Which filler do you choose?', options: ['Cotton fleece', 'Firm veg-tan at 1.5–1.9 mm', 'Two 1 mm sheets of craft foam', 'Layers of stiff cardboard'], answer: 1, explain: 'Veg-tan at 1.5–1.9 mm holds a crisp, carved dome. Foam and fleece give a softer, rounder one, and cardboard is what cheap straps use, so avoid it.' },
    { q: 'Thin water-based cement on both faces has gone tacky after 3 minutes. What comes next?', options: ['Add superglue along the edges to lock the layers', 'Press at 1 bar or more, then sew after 30–60 minutes', 'Leave it open for 4 hours, then press and sew at once', 'Lay the faces together lightly and start sewing straight away'], answer: 1, explain: 'Water-based cement is tacky in 2–3 minutes. Press at 1 bar or more and leave it 30–60 minutes before sewing. Never laminate with superglue: it cracks in flex.' },
  ],

  'sm-grained': [
    { q: 'The pattern on a scrap of grained calf repeats, and it stays crisp when you flex it. What do you have?', options: ['A milled grain', 'A shrunken grain', 'A natural goat grain', 'A printed grain'], answer: 3, explain: 'A printed grain repeats and stays crisp when flexed. A milled grain never repeats, and milled and shrunken grains soften and stretch.' },
    { q: 'You cut a scrap of blue grained leather and the section shows a cognac core. How do you plan the edge?', options: ['Burnish it, so the core darkens to match the blue', 'Paint it cognac, to match the colour of the core', 'Paint it blue, and colour any skive that will show', 'Leave it raw, so the core shows as a design line'], answer: 2, explain: 'Paint to the surface colour, not the core colour, and colour any skive or flap that will show the core. A finished grain like this never takes a burnished edge.' },
    { q: 'You are skiving a fold flap on an Epsom-type printed top. Which setup do you use?', options: ['Face down on glass, skiving dry from the flesh', 'Face up on glass, skiving the print away at the fold', 'Face down on a soft board, with the grain dampened first', 'Face down on glass, with the face warmed so it softens'], answer: 0, explain: 'The pattern lives in the top fraction of a millimetre, so skive only from the flesh. The print is heat-set, and moisture or a hot tool can flatten it.' },
    { q: 'A 2.4 mm tonal seam vanishes into a coarse pebbled top. What do you change?', options: ['A finer pitch with a darker thread', 'A bolder pitch with an off-white thread', 'A wider margin with the same thread', 'A deeper groove, so the thread sits lower'], answer: 1, explain: 'On a coarse pebble a fine stitch disappears, and pebble swallows tonal thread. Makers go to about 2.8–3.2 mm with an off-white thread that sits on top of the texture.' },
    { q: 'You are laminating a strap with a nubuck top. How do you protect the face and finish the edge?', options: ['Wipe stray cement off the nap, then burnish the edge', 'Mask the face with low-tack tape, then burnish the edge', 'Wipe stray cement off the nap, then stain the edge', 'Mask the face with low-tack tape, then stain the edge'], answer: 3, explain: 'You can’t wipe contact cement out of nap, so mask the face before gluing. Nubuck can’t be burnished either: stain or paint the edge.' },
  ],

  'sm-tools': [
    { q: 'You have a rotary cutter and a fresh utility knife on the bench, and a piece of firm veg-tan to cut. How do you cut it?', options: ['Rotary cutter along a steel rule, in one firm pass', 'Knife on a steel rule, in several light passes', 'Rotary cutter freehand, following the scribed line', 'Knife held at a slant, in one heavy pass'], answer: 1, explain: 'A rotary cutter tears fibres on firm leather, so keep it for linings, if at all. Hold the knife vertical against a steel straightedge and take several light passes.' },
    { q: 'You are laying out the course’s default kit for a first strap. Which matched set is it?', options: ['2.7 mm pitch, 0.40–0.45 mm thread, VB #10 iron', '2.25 mm pitch, 0.35 mm thread, VB #12 iron', '3.38 mm pitch, 0.55–0.6 mm thread, VB #8 iron', '3.0 mm pitch, 0.45–0.55 mm thread, VB #9 iron'], answer: 3, explain: '3.0 mm pitch with 0.45–0.55 mm thread, a JJ 004 needle and a VB #9 iron is the default. The 2.7 mm set is fine dress, 2.25 mm is premium work, and 3.38 mm is for bolder 20–24 mm straps.' },
    { q: 'You are about to strike a pricking iron. Your bench has a granite slab, a self-healing mat and a poly pad. What goes under the strap?', options: ['The granite slab', 'The self-healing mat', 'The poly pad', 'The bare bench top'], answer: 2, explain: 'A poly pad or poundo board protects the tools. Never punch on stone or on a self-healing mat, which a punch goes straight through. Keep the granite for skiving and hammering.' },
    { q: 'Your strap will have painted edges. Which bevel do you set up for?', options: ['0.5–0.7 mm', '1.0–1.2 mm', '1.5–2 mm', '2.5–3 mm'], answer: 0, explain: 'Use an edge beveller of 0.5–0.7 mm. Larger bevels crack paint at the folds.' },
    { q: 'Halfway through a cut you are pressing hard to get the knife through. What do you do?', options: ['Lean in with a firmer grip and finish the pass', 'Put on a cut-resistant glove and carry on', 'Stop and sharpen the knife', 'Change to the rotary cutter for the rest'], answer: 2, explain: 'Most leatherwork injuries come from forcing a blunt blade. A dull knife is the greater hazard because it needs force, so if you have to push hard, stop and sharpen.' },
  ],

  'sm-design': [
    { q: 'The lug gap on your watch measures 20.0 mm. Which finished width at the lug passes?', options: ['20.2 mm', '19.9 mm', '19.6 mm', '19.0 mm'], answer: 1, explain: 'The strap must be no wider than the gap and no more than 0.2 mm narrower. Wider and it binds, narrower and it shuffles and looks cheap. Only 19.9 mm sits in that band.' },
    { q: 'You are sizing from the wearer’s old strap. What do you measure on the long piece?', options: ['Its overall length, then add 5 mm', 'From the tip to the last hole, then double it', 'From the spring bar to the hole in use', 'From the spring bar to the last hole'], answer: 2, explain: 'Measure from the bar to the hole the wearer actually uses, not the overall length, because old straps have stretched.' },
    { q: 'A wearer’s wrist measures 17.5 cm. Which finished pair do you start from?', options: ['105/65', '125/80', '130/90', '115/75'], answer: 3, explain: 'About 115/70–75 fits 16.5–19 cm, and 115/75 is the course’s regular size. 105/65 suits 14.5–17 cm and 125/75–80 suits 18.5–21 cm. Cross-check against the lug-width table.' },
    { q: 'You are drafting a premium dress strap for a 22 mm lug. Which taper fits?', options: ['22 → 18', '22 → 20', '22 → 16', '22 → 14'], answer: 0, explain: 'Premium dress makers standardise on 4 mm, so 22 → 18, and cap it at about 5 mm. A 2 mm taper such as 22 → 20 is the usual sports strap.' },
    { q: 'Your draft shows a 20 mm flap beyond both the lug fold and the buckle fold. What do you change?', options: ['Leave both flaps as they are', 'Shorten the lug flap to 12 mm', 'Lengthen both flaps to 40 mm', 'Lengthen the buckle flap to 25 mm or more'], answer: 3, explain: 'Allow about 20 mm at the lug end and at least 25 mm at the buckle end. The flap has to wrap the hardware and still leave a tail to return under the top.' },
  ],

  'sm-sharpen': [
    { q: 'On the 1000-grit stone you feel a burr at one end of the edge but not the other. What do you do?', options: ['Move up to 5000 grit and let it even out', 'Flatten the back now to remove the burr', 'Keep honing until the burr runs the whole edge', 'Rock the blade to bring pressure to the far end'], answer: 2, explain: 'Work the whole edge until you can feel a slight burr along the far side, and keep the angle constant. A rocking hand rounds the bevel.' },
    { q: 'You pick up a charged strop. Which way does the blade travel?', options: ['Spine leading, alternating sides', 'Edge leading, pressing lightly into the leather', 'Edge leading, lifting the blade at the end of each pass', 'Sideways along the strop, on one face of the blade'], answer: 0, explain: 'Draw the edge backwards with the spine leading, alternating sides. Pushed edge-first, the blade cuts the strop and rounds its edge.' },
    { q: 'On scrap from the same hide, the knife tears instead of slicing. What next?', options: ['Press harder so the blade bites', 'Dampen the scrap and cut again', 'Go back a grit and work up again', 'Test on scrap from a softer hide'], answer: 2, explain: 'A sharp edge slices veg-tan cleanly with no drag. If it tears or skates, go back a grit and work up again.' },
    { q: 'You are six skiving cuts in and notice you are starting to push. What do you do?', options: ['Finish the flap, then strop before the next piece', 'Steepen the blade so it bites without pushing', 'Go back to the 1000-grit stone', 'Stop and strop before the next cut'], answer: 3, explain: 'Strop before every session and every 5–10 skiving cuts. The moment you notice you are pushing, stop and strop.' },
  ],

  'sm-cut': [
    { q: 'Top and lining are both skived and ready. When do you cut the true outline?', options: ['Before gluing, on each layer on its own', 'Before gluing, on the top only', 'After stitching, through the top layer only', 'After gluing, through all the layers at once'], answer: 3, explain: 'Cut every layer oversize, glue them into one laminate, then make one true 90° cut through everything, so the layers can never be out of line.' },
    { q: 'Your template is 20 mm wide at the lug end. What is the narrowest lining blank you should cut there?', options: ['20 mm', '30 mm', '40 mm', '35 mm'], answer: 2, explain: 'Cut the lining at least 20 mm wider than the template, about 10 mm each side, so it is wider than the top blank and can never fall short. The final cut trims it exactly.' },
    { q: 'After the final cut, the lining stands proud of the top along one side. What went wrong?', options: ['The blade leaned off vertical', 'The lining blank was cut too wide', 'The card template was too thick', 'The lining was thinner than the top'], answer: 0, explain: 'A blade that leans even a few degrees leaves the lining proud of the top on one side. Sight down the blade before each pass so top and lining share one edge.' },
    { q: 'The flanges of a padded strap won’t lie flat for a clean pre-cut. What do you do?', options: ['Cut the flanges first, then add the filler', 'Keep it oversize, stitch it, then trim', 'Make one heavy cut to flatten the flange', 'Cut from the lining side with the dome held down'], answer: 1, explain: 'Some makers keep the strap oversize through stitching, then trim to the final outline. It suits padded straps whose flanges won’t lie flat. The course default is still to trim after gluing, before stitching.' },
    { q: 'You scribed the outline on the grain side. Where must the fold, trim and slot marks end up?', options: ['On the grain side, where you can see them', 'On the card template only', 'On the flesh side', 'On the edge of the blank'], answer: 2, explain: 'Push an awl through the template’s points so they appear on the flesh side. That is the side you will skive and glue.' },
  ],

  'sm-skive': [
    { q: 'Your blade keeps skating off the leather without cutting. What do you change?', options: ['Lower the blade until it lies almost flat', 'Raise the blade to about 30°', 'Keep the angle and push harder', 'Raise the blade to about 10–15°'], answer: 3, explain: 'Below about 5° the blade skates, and above about 20° it cuts straight through. The working window is about 10–15°.' },
    { q: 'Soft chrome-tan calf creeps under your blade. How do you stop it?', options: ['Tape it flat with low-tack tape', 'Dampen it with a sponge so it grips the plate', 'Move it to a softer board so the blade sinks in', 'Take one heavy pass before it can move'], answer: 0, explain: 'Low-tack tape on the grain side, or taping it to the plate, stops soft leather creeping. Never dampen chrome-tan: that trick is for veg-tan only.' },
    { q: 'You dry-fold a skived lug flap and the doubled fold stands proud of the strap body. What next?', options: ['Glue it and hammer it flat', 'Cut a new flap and start over', 'Take another pass and test again', 'Skive the strap body to match it'], answer: 2, explain: 'The doubled fold should match the strap body. If it is fatter, take another pass. Only a hole in the flap means cutting a new one.' },
    { q: 'A section through your skive shows a ridge instead of a smooth taper. What caused it?', options: ['A blade held too low to bite', 'One heavy pass', 'Veg-tan dampened on the flesh side', 'Skiving on a glass plate'], answer: 1, explain: 'One heavy pass leaves a ridge. Several light pulling, slicing passes build a smooth taper, each lifting a thin, even shaving.' },
    { q: 'You are skiving the linings of a two-piece strap. Which ends do you skive?', options: ['All four ends, down to a feather', 'Both ends of the long lining, the short left full', 'Short lining at both ends, long lining at the lug end', 'Long lining at the tip end, short lining at the buckle end'], answer: 2, explain: 'Skive the short lining lightly at both ends and the long lining only at its lug end. The tip end stays full. A lining end that meets a fold must disappear into it.' },
  ],

  'sm-reinforce': [
    { q: 'You are reinforcing a padded strap. Where does the layer go?', options: ['Full length on the top’s flesh side, edge to edge', 'On the filler only, stopping at each fold', 'Down the centre of the top and through the folds', 'On the lining and around the folds'], answer: 3, explain: 'A padded strap takes it on the lining and around the folds, stopping short of the edges. Full length on the top’s flesh is the flat-strap placement.' },
    { q: 'You are bonding a sheet of Velodon to the flesh of the top. Which adhesive do you use?', options: ['Water-based contact cement', 'Solvent contact cement', 'PVA wood glue', 'Superglue'], answer: 1, explain: 'Use solvent contact cement for nylon and synthetic sheets. Water-based glue grips them poorly. Thin coat on both faces, then wait for tack.' },
    { q: 'You are reinforcing with a stiff 6–8 mm tear-resistant tape. How far does it run?', options: ['Down the centre, carried on round both folds', 'Down the centre, stopping before the folds', 'Along both edges and into the folds', 'Across the strap at each adjustment hole'], answer: 1, explain: 'Tape stays down the centre only, never in the folds, because a stiff tape cracks in a fold. A thin flexible non-woven is what can go at the pins.' },
    { q: 'Reinforcement is glued on and part of it has been folded. How do you press it?', options: ['With a rubber roller, pressed firmly along its length', 'With a polished hammer on the grain', 'With a wooden block over a sheet of paper', 'Between two bare steel rules, clamped'], answer: 2, explain: 'A wooden block over a sheet of paper presses without stretching the leather. Never run a roller over reinforcement that has been folded.' },
  ],

  'sm-glue': [
    { q: 'You are marking up a strap for gluing. How far from each fold does the glue stop?', options: ['14 mm at the lug, 10 mm at the buckle', '3 mm at the lug, 5 mm at the buckle', '10 mm at the lug, 14 mm at the buckle', '20 mm at the lug, 25 mm at the buckle'], answer: 2, explain: 'No glue within 10 mm of the lug fold or 14 mm of the buckle fold. That keeps the folds free to roll and the bar channel clear.' },
    { q: 'One minute after coating, your knuckle comes away with cement on it. What do you do?', options: ['Wait until it is tacky and nothing transfers', 'Lay the lining now, while it can still slide', 'Add a second coat to bring the tack on faster', 'Wipe it off and start again with a heavier coat'], answer: 0, explain: 'Contact cement bonds dry-to-dry: tacky, not wet, and nothing transfers to the knuckle. A thin water-based coat on leather takes about 2–3 minutes.' },
    { q: 'Both linings are tacky and ready to lay. How do you lay them?', options: ['Both flat, then bend the strap once the bond has set', 'Both bent round a former, at the same curve', 'The long lining flat, the short one over a former', 'The long lining over a former, the short one flat'], answer: 3, explain: 'Lay the long lining while the strap is bent into a wrist curve, and the short lining flat. That builds the curve into the laminate, so the top never wrinkles.' },
    { q: 'A friend says to glue only spots along the strap, because full-face gluing stiffens it. What do you do?', options: ['Spots of glue every 10 mm along the centreline', 'One thin, even coat up to the stops', 'Glue along the two long edges, leaving the centre bare', 'A heavy coat on one face, leaving the other dry'], answer: 1, explain: 'A thin full coat on both faces is right. Full-face gluing does not stiffen a strap, but puddles do.' },
    { q: 'You have just pressed a no-sew strap. When is it ready?', options: ['After 24 hours under weight', 'After 2–3 minutes, once it is tacky', 'After 4 hours in a warm place', 'After 30–60 minutes on the bench'], answer: 0, explain: 'A stitched strap waits 30–60 minutes before cutting and stitching. A no-sew strap needs 24 hours under weight.' },
  ],

  'sm-mark': [
    { q: 'You are marking a first strap at 3.0 mm pitch. What do you set the dividers to?', options: ['1.5 mm', '2 mm', '3.5–4 mm', '2.75–3 mm'], answer: 3, explain: '2.75–3 mm is the default for a 3 mm pitch. About 2 mm belongs with the finer pitch and thread of a premium slim strap.' },
    { q: 'Your scored stitch line drifts in and out along the strap, though your hand was steady. What do you check first?', options: ['The depth of the score', 'The width and the edge', 'The pitch of your iron', 'The thickness of the lining'], answer: 1, explain: 'A stitch line follows the edge, and leather can shift during gluing. Re-measure the width and put the edge right before you mark again.' },
    { q: 'Your top is 1.1 mm thick and you want the thread recessed in a groove. How do you cut it?', options: ['One firm pass with the groover', 'Freehand with a knife, along the score', 'Two or three light passes', 'Deep enough to reach the reinforcement'], answer: 2, explain: 'A groover stretches stock under about 1.6 mm, so take 2–3 light passes, or dampen and press a line instead.' },
    { q: 'The edge leg of your dividers keeps digging in and the line jumps. What is the fix?', options: ['File the edge leg shorter and rounder', 'Press harder so the leg stays in the leather', 'Dampen the edge so the leg slides along it', 'Swap the legs so the scoring leg rides the edge'], answer: 0, explain: 'Filing the edge leg a little shorter and rounder makes it ride the edge without digging.' },
    { q: 'Your scored line runs right up to the lug fold. Where should the stitching stop?', options: ['On the fold line itself', 'A few millimetres behind the fold', 'Round the fold and into the flap', 'At the first adjustment hole'], answer: 1, explain: 'Mark the starts and stops a few millimetres behind each fold, so the needle never pierces the fold zone.' },
  ],

  'sm-prick': [
    { q: 'You are pricking the long piece. Where do you start?', options: ['At the lug end, working down to the tip', 'Halfway down one side, where it won’t show', 'At the apex of the tip, on the centreline', 'Level with the first adjustment hole'], answer: 2, explain: 'Put a hole exactly on the centreline at the apex, then step out symmetrically on both sides. Everything else follows from the tip.' },
    { q: 'The last gap on a straight won’t divide evenly at 3 mm pitch. What do you do?', options: ['Put the odd stitch at the tip, where the seam turns', 'Leave one short stitch at the end of the run', 'Change to a different iron for the last few holes', 'Spread the difference over the last two or three holes'], answer: 3, explain: 'Spread the difference over the last two or three holes of the straight. Never do it at the tip, where the eye looks first.' },
    { q: 'The holes look straight on the top, but on the lining side they wander off the line. What is the likely cause?', options: ['The iron leaned as you struck', 'The mallet was too heavy', 'The iron’s pitch is too fine for the leather', 'The divider line was scored too lightly'], answer: 0, explain: 'A lean of only 5° walks the exit holes off the line on the back. Hold the iron dead upright: at 3 mm pitch, a hole half a millimetre off the line is visible.' },
    { q: 'You are moving the long iron along a straight. How do you keep the spacing unbroken?', options: ['Measure each new strike from the edge with dividers', 'Set its first prong in the last hole of the last strike', 'Leave one pitch of clear leather, then fill it in later', 'Line up its last prong with the start of the seam'], answer: 1, explain: 'Walk the iron: set the first prong into the last hole of the previous strike and strike again, so the spacing never breaks.' },
    { q: 'The curve at the tip is too tight for both prongs of the 2-prong iron. What do you do?', options: ['Rock the long iron round the curve', 'Skip those holes and add them later by eye', 'Widen the pitch until the curve ends', 'Cant it so only one prong bites at a time'], answer: 3, explain: 'Keep the first prong in the last hole so the spacing carries on, and on tight curves cant the iron so only one prong bites at a time.' },
  ],

  'sm-atelier': [
    { q: 'Your 3 mm seam is even and you want to sew a slim strap at atelier grade. Which spec do you move to?', options: ['3.85 mm pitch, 0.55 mm thread, 3 mm margin', '3.0 mm pitch, 0.5 mm thread, 3 mm margin', '2.7 mm pitch, 0.55 mm thread, 1 mm margin', '2.45 mm pitch, 0.35 mm linen, 2 mm margin'], answer: 3, explain: 'Measured across premium makers, the spec is about 2.45 mm pitch in 0.35 mm linen, about 2 mm from the edge. 3.0 mm with a 3 mm margin stays the first-strap default, and 3.85 mm is the rugged grade.' },
    { q: 'You own a 2.7 mm iron and want a 2.45 mm seam. What do you do?', options: ['Walk the 2.7 mm iron tighter on each strike', 'Keep the iron and change to a thicker thread', 'Use an iron made for 2.45 mm', 'Keep the iron and narrow the margin to 2 mm'], answer: 2, explain: 'A 2.7 mm iron walked tight never looks like a true 2.45. Use an iron made for the pitch.' },
    { q: 'A 2.45 mm seam in 0.35 mm linen sits 3 mm from the edge and looks lost. What do you change next time?', options: ['Bring the margin in to about 2 mm', 'Change to a heavier 0.55 mm thread', 'Widen the pitch to 3 mm', 'Add a second row of stitches inside it'], answer: 0, explain: 'Scale the margin with the pitch. About 2 mm suits 2.25–2.5 mm pitch with 0.35 mm thread. Keep 2.75–3 mm for 3 mm pitch and heavier thread.' },
    { q: 'You turn a commercial strap over. The stitches are white on the face and tan on the underside. How was it sewn?', options: ['A hand saddle stitch', 'A lockstitch machine', 'A hand saddle stitch in two threads', 'A saddle stitch stained on the underside'], answer: 1, explain: 'A saddle stitch is one thread worked by two needles, so it shows the same colour on both faces. One colour per face means a lockstitch machine, with needle thread on top and bobbin thread below.' },
    { q: 'Sewing a 1.5 mm micro-stitch, you see the leather starting to cut between the holes. What do you change?', options: ['Pull harder so the thread beds in', 'Switch to a thicker thread', 'Take out the full-length reinforcement', 'Pull every stitch to the same, lighter tension'], answer: 3, explain: 'Over-tension cuts the leather between close holes. Pull every stitch to the same, lighter tension, and keep the full-length reinforcement: at this density the hole line behaves like a perforation.' },
  ],

  'sm-edges': [
    { q: 'You are planning the finish on an all-veg-tan strap. Which parts get the burnish?', options: ['The long edges and the tip', 'Every edge, including horns and fold spine', 'The lug horns and the fold spine only', 'The long edges, the tip and the fold spine'], answer: 0, explain: 'Finish the long edges and the tip. Leave the lug horns and the fold spine bare, because finish there rubs off. On the folds, use only gum or Tokonole.' },
    { q: 'You can see a step between top and lining along the edge. What do you do before bevelling?', options: ['Burnish it hard until the step closes', 'Take a bigger bevel to hide the step', 'Sand along it until it reads as one face', 'Fill the step with gum tragacanth'], answer: 2, explain: 'Level first: run a sanding block along the edge until top and lining read as one flat face with no step. The bevel comes next.' },
    { q: 'At 400 grit you can still see cross-scratches on the edge. What went wrong?', options: ['You skipped the bevel', 'You sanded across the edge', 'You used too little burnishing agent', 'You started at too fine a grit'], answer: 1, explain: 'Sand lengthwise, never across: 220 → 400 → 600, then 1000–1200 for glass. Each grit removes the previous one’s scratches.' },
    { q: 'A customer wants a glass edge, not a working edge. How many rounds of agent and burnish do you plan?', options: ['One', 'Two', 'Ten or more', 'Four to six'], answer: 3, explain: 'Two rounds suit a working strap, and four to six give a glass edge. Each round seals and deepens the shine.' },
    { q: 'You want the edge darker than the leather. Where does edge dye fit in?', options: ['After the sanding, before the agent', 'Before levelling, on the raw edge', 'After the wax, as the last coat', 'Between each round of burnishing'], answer: 0, explain: 'Brush on edge dye after sanding and let it dry. The agent and burnishing follow, and wax comes last.' },
  ],

  'sm-edgepaint': [
    { q: 'You are preparing a chrome-lined edge for paint. A friend says to slick it with Tokonole first. What do you do?', options: ['Slick it, so the paint flows more smoothly', 'Slick it, then wax it, so the paint can’t soak in', 'Skip the sanding and use Tokonole on the raw edge', 'Leave it out, because paint won’t key to it'], answer: 3, explain: 'Sand from about 180 up to 400 and singe off any fuzz instead. Paint won’t key to a slicked edge, so no burnishing agent goes under it.' },
    { q: 'Your strap is cut at exactly 20.0 mm for a 20.0 mm lug gap. How many coats do you stop at?', options: ['Two', 'Four', 'Six', 'Eight'], answer: 0, explain: 'Every coat adds width. Three to four thin coats is the course standard, but a strap cut exactly to the lug gap stops at two.' },
    { q: 'You want to smooth a coat with a hot edge iron, and its dial reads 120 °C. What do you do?', options: ['Glide it quickly so it can’t scorch', 'Press it down firmly for one pass', 'Turn it down to under 90 °C', 'Save it for the last coat only'], answer: 2, explain: 'Keep a hot edge iron under 90 °C. The other way to smooth a coat is light sanding: 400–600 for early coats, 800–1200 later.' },
    { q: 'Paint keeps running on the curve of the tip. What could have prevented it?', options: ['A bigger bevel at the tip', 'A primer coat underneath', 'A Tokonole burnish first', 'One thicker coat of paint'], answer: 1, explain: 'A primer fills the fibres and stops later coats running on curves. Thin coats still matter, and a big bevel only gives the paint a sharp corner to crack on.' },
    { q: 'You have mixed a paint to match the leather. What do you do before it goes on the strap?', options: ['Add a drop of wax so it flows evenly', 'Test a stripe on an offcut first', 'Thin it until it matches when wet', 'Warm it so the colour stays true'], answer: 1, explain: 'Mix the paint and test a stripe on an offcut, because it dries lighter or darker.' },
  ],

  'sm-holes': [
    { q: 'The buckle tongue measures 1.8 mm. Which round punch do you pick?', options: ['1.0 mm', '1.5 mm', '2.5 mm', '1.8 mm'], answer: 3, explain: 'Pick a punch equal to or a little larger than the tongue. 1.8 mm is also a common factory size.' },
    { q: 'You fit the buckle and the tongue grips in the slot. The fold isn’t glued yet. What do you do?', options: ['Lengthen the slot', 'Glue the fold and let the leather wear in', 'Punch a second slot beside the first', 'File the tongue thinner'], answer: 0, explain: 'Check the tongue before the buckle fold is glued. It should sit and swing freely, and a slot that grips gets lengthened.' },
    { q: 'Spaced by eye, your holes have drifted. How do you avoid that on the next strap?', options: ['Punch from the tip toward the buckle', 'Change to a larger punch', 'Prick the centres through a template', 'Score each position with a groover'], answer: 2, explain: 'Prick the hole centres through your template or a card pattern glued on. Freehand spacing drifts.' },
    { q: 'A wearer wants finer adjustment over the same span of holes. What do you change?', options: ['Use a larger punch', 'Use a finer pitch, such as 5 mm', 'Move the last hole nearer the tip', 'Change to oval holes'], answer: 1, explain: 'A finer pitch gives finer adjustment over the same span. Measured commercial straps run from eight holes at 5 mm to six or seven at about 7.3 mm. This course uses 6–7 mm.' },
  ],

  'sm-keepers': [
    { q: 'You need a butt-sewn keeper for a strap 2.5 mm thick and 18 mm wide. How long is the strip?', options: ['28 mm', '41 mm', '46 mm', '56 mm'], answer: 2, explain: 'Length = 4 × thickness + 2 × width, so 4 × 2.5 + 2 × 18 = 46 mm.' },
    { q: 'Your keeper strip is cut, thinned and skived. What do you do before closing it?', options: ['Fit it on the strap to test it', 'Finish both long edges', 'Stitch it to the buckle fold', 'Condition it with neatsfoot oil'], answer: 1, explain: 'Finish both long edges while the strip is flat. Once the keeper is closed you can’t reach them.' },
    { q: 'Your floating keeper won’t slide on the finished strap. What do you change on the next one?', options: ['Make it slightly longer than the fixed keeper', 'Make it the same length as the fixed keeper', 'Make it slightly shorter than the fixed keeper', 'Cut it from a thicker strip of leather'], answer: 0, explain: 'Make the floating keeper slightly longer than the fixed one so it slides.' },
    { q: 'You are fitting the fixed keeper. Where do its ends go?', options: ['Stitched into the buckle fold itself', 'Glued to the outside of the lining', 'Wrapped round the buckle bar', 'Under the buckle flap, 10 mm from the fold'], answer: 3, explain: 'Pare the ends, glue them and trap them under the buckle flap about 10 mm from the fold, between the stitch lines. Stitch the keeper into the fold and you can’t crease or finish the edge afterwards.' },
  ],

  'sm-folds': [
    { q: 'Your lug fold is too bulky to pass between the bar and the case. What do you do first?', options: ['Hammer the fold flat on marble', 'Trim the strap narrower at the lug', 'Skive until the doubled fold is about one layer', 'Change to a thinner former for the channel'], answer: 2, explain: 'Skive so the doubled fold is about one layer: the fold about half thick, the tail feathered. Dry-test it, and try a sample in the lugs.' },
    { q: 'You are closing a lug fold. Where does the glue go?', options: ['On the tail tip and its landing zone', 'Inside the channel, so the bar stays put', 'Over the whole flap, channel included', 'Along the outside of the fold spine'], answer: 0, explain: 'Glue only the tail tip and its landing zone. The channel stays glue-free, with a former slightly larger than the pin holding it open.' },
    { q: 'Your flat strap body measures 2.2 mm. What figure do you check against the space between the lug holes and the case?', options: ['About 2.8 mm over the bar', 'About 1.1 mm, half the body', 'About 4.4 mm, twice the body', 'The 2.2 mm body thickness'], answer: 0, explain: 'A 2.2 mm flat strap measures about 2.8 mm over the bar. Check that figure, not the body thickness.' },
    { q: 'On a watch designed for a bracelet, the strap sits under the lug tips and leaves “ears”. What do you do?', options: ['Thicken the whole strap until it sits level', 'Add a layer over the lug end only', 'Fit curved ends to close the gap', 'Fold round a larger former'], answer: 1, explain: 'Don’t thicken the whole strap. Laminate an extra layer over the lug end only, so the face rises flush with the lugs while the body stays slim, and skive its back edge to a feather.' },
    { q: 'A customer asks for curved ends on a watch that takes straight straps. What do you tell them?', options: ['They will give a perfectly flush fit', 'They will work if you add an insert', 'They will make the gap bigger', 'They will work with a straight bar'], answer: 2, explain: 'Never fit curved ends to a watch that takes straight straps: the gap gets bigger. They are for cases with short lugs and holes close to the body, which need a curved bar.' },
  ],

  'sm-finish': [
    { q: 'You are buffing a freshly dyed top and the cloth still picks up colour. What do you do?', options: ['Keep buffing until the cloth stays clean', 'Seal it now, so the loose dye is trapped', 'Apply conditioner to lock the dye in', 'Add a coat of neatsfoot oil, then stop'], answer: 0, explain: 'Buff until a white cloth comes away clean. Conditioners are not sealers, and loose dye has to come off now.' },
    { q: 'You rub a damp white cloth hard on a hidden spot of a sealed strap, and colour comes off. What next?', options: ['Another sealing coat', 'A coat of neatsfoot oil', 'Another coat of dye', 'Nothing, because it settles with wear'], answer: 0, explain: 'Clean cloth means done. Colour on the cloth means another sealing coat.' },
    { q: 'A strap sealed on its face bled dye at the buckle. What was missed?', options: ['A conditioning coat', 'A second coat of dye', 'The undyed lining', 'The edges'], answer: 3, explain: 'Seal with Resolene thinned 1:1 with water, two or three light coats, and seal the edges too. One maker found dye bleeding at the buckle where he had not.' },
    { q: 'You have just conditioned a strap and want it dry quickly. What do you do?', options: ['Warm it with a heat gun', 'Let it dry flat, with no heat', 'Leave it near a radiator', 'Bend it round a warm bottle'], answer: 1, explain: 'Apply a thin coat, buff with a clean cloth and let it dry flat, never with heat. At most two or three thin coats in a session.' },
    { q: 'Your veg-tan needs hand-dyeing. When do you do it?', options: ['After gluing on the lining', 'After stitching, before the edges', 'Before assembly, while it is flat', 'After the edges are finished'], answer: 2, explain: 'Dye hand-dyed veg-tan before assembly, while the piece is flat, and leave the lining undyed. Buying tannery-dyed leather skips this altogether.' },
  ],

  'sm-qc': [
    { q: 'The lug gap is 20.0 mm and your strap measures 19.7 mm. What is your verdict?', options: ['Pass, because a narrower strap can’t bind', 'Pass, because it is within 0.5 mm', 'Fail, because it is 0.3 mm under', 'Fail, because it must match exactly'], answer: 2, explain: 'The pass band is the lug gap down to 0.2 mm under it. At 19.7 mm this strap is 0.3 mm narrow, so it fails.' },
    { q: 'You find one uneven stitch in a run of sixty. What does the check call for?', options: ['Re-stitch that run', 'Hammer that stitch flat', 'Accept it, as one in sixty is allowed', 'Darken it with a touch of edge paint'], answer: 0, explain: 'One uneven stitch in sixty means re-stitching that run. The seam also needs an even slant, no pierced thread and ends on the lining side.' },
    { q: 'The bar slides freely, but its holes are 0.8 mm out of line. What is your verdict?', options: ['Pass, because it slides freely', 'Fail, because the limit is 0.5 mm', 'Pass, because the limit is 1 mm', 'Fail, because any offset at all fails'], answer: 1, explain: 'The bar must slide freely and its holes must align within 0.5 mm. At 0.8 mm it fails, however well it slides.' },
    { q: 'When do you test-fit the strap on the watch?', options: ['After the last coat of paint', 'After conditioning, as the last step', 'Only once the holes are punched', 'Before the final paint coats'], answer: 3, explain: 'Test-fit before the final paint coats, leaving room for the paint.' },
  ],

  'sm-classic-1': [
    { q: 'Your job card says firm veg-tan top and Zermatt lining. Which edge route do you write down at step 1?', options: ['Painted', 'Burnished on the top only', 'Burnished', 'Raw and waxed'], answer: 0, explain: 'Burnish only if top and lining are both firm veg-tan. A Zermatt or Alsavel lining means paint, and you choose the route now.' },
    { q: 'Your leather was dyed at the tannery. What happens to step 8, dye and seal the top?', options: ['You skip it', 'You dye it again to even it out', 'You seal it, then re-dye it', 'You dye the lining to match'], answer: 0, explain: 'Step 8 is for hand-dyed veg-tan only. Buying tannery-dyed leather lets you skip it, and the lining stays undyed.' },
    { q: 'The top is skived and reinforced. When do you punch the tongue slot?', options: ['After the lining is glued on', 'After the buckle fold is closed', 'After the strap is stitched', 'Now, with the short piece still flat'], answer: 3, explain: 'Step 13 punches the slot with the short piece still flat, centred on the buckle fold and about 10 mm long.' },
    { q: 'You want a size code such as 20-16 stamped on both pieces. When do you emboss it?', options: ['Into the top, after stitching', 'Into the lining, while it is flat', 'Into the lining, after the final cut', 'Into the top, before dyeing'], answer: 1, explain: 'Stamp the lining now, while it is flat. A size code on both pieces means a pair can never be mismatched and a repeat order is exact.' },
    { q: 'Which order does the classic lined strap follow?', options: ['Cut, glue, skive, reinforce, mark, trim, stitch, prick, edges', 'Cut, skive, glue, reinforce, trim, stitch, mark, prick, edges', 'Cut, reinforce, skive, mark, prick, glue, stitch, trim, edges', 'Cut, skive, reinforce, glue, trim, mark, prick, stitch, edges'], answer: 3, explain: 'Cut, skive, reinforce, glue the lining, trim, mark, prick, stitch, finish the edges, then holes and keepers. Every other construction varies this order.' },
  ],

  'sm-classic-2': [
    { q: 'You have creased both folds round formers. Why do you open them again before the final cut?', options: ['The creases set better with air round them', 'That cut would slice a keeper already in place', 'The lining has to wrap round the bar first', 'Closed folds stop the cement from curing'], answer: 1, explain: 'The folds are closed after the final cut, because that cut runs along every edge and would slice through a keeper already in place.' },
    { q: 'Closing the lug fold, you find the tail runs past its glue stop. What do you do?', options: ['Glue it down past the stop', 'Fold the end back on itself', 'Trim it to end at the stop', 'Cut a new top and start again'], answer: 2, explain: 'Each tail slips into the unglued pocket between top and lining. If it runs past its glue stop, trim it to end there, and glue only the tail tip.' },
    { q: 'You are closing the buckle end. What is the right sequence?', options: ['Buckle on first, then trap the keeper ends', 'Close the fold first, then thread the buckle on', 'Stitch the keeper in, then fit the buckle', 'Glue the keeper over the tail, then add the buckle'], answer: 0, explain: 'Put the buckle on first and trap the skived fixed-keeper ends under the tail, about 10 mm from the fold.' },
    { q: 'You laid the linings ten minutes ago and want to make the final cut. What do you do?', options: ['Cut now, while the cement is still soft', 'Cut the top now and the lining later', 'Leave it 24 hours under weight first', 'Wait until it has had 30–60 minutes'], answer: 3, explain: 'Step 18 leaves the laminate 30–60 minutes before cutting. 24 hours under weight is for a no-sew strap.' },
  ],

  'sm-classic-3': [
    { q: 'You are fitting a quick-release bar at step 30. What has to happen first?', options: ['Condition the strap', 'Cut the notch', 'Run the ten checks', 'Stitch the fold closed again'], answer: 1, explain: 'Spring bars go in at step 30, but a quick-release bar needs its notch cut first.' },
    { q: 'You reach step 26 on a strap with a chrome lining. Which route do you take?', options: ['Sand to 1200, gum, slicker and canvas, then wax', 'Thin paint coats over the horns and the fold spine', 'One thick coat of paint, then canvas to burnish it', 'Thin paint coats, sanded between, none on the horns'], answer: 3, explain: 'A chrome lining can’t burnish, so it takes step 26b: thin coats, sanding 400–600 between, heat-set, with none on the horns or the fold spine.' },
    { q: 'Another maker tells you they paint their edges before sewing. What do you make of that?', options: ['It is a documented variation', 'It only works on burnished edges', 'It is a mistake that cracks the paint', 'It is only possible on an unlined strap'], answer: 0, explain: 'The order varies more here than anywhere else. Some makers paint before sewing, some trim after sewing and some punch holes at the very end. This course finishes edges after stitching.' },
    { q: 'Your seam is stitched and set, and you skipped the crease at step 23. What can you still do?', options: ['Nothing, because a crease must go on first', 'Crease the lining side only', 'Crease now, before the edge coats', 'Crease after the last coat of paint'], answer: 2, explain: 'Some makers crease after stitching instead: stitch, crease, then the edge coats.' },
    { q: 'You reach step 28 on the long piece. Which hole layout follows the course?', options: ['Ø 3–4 mm, 10 mm pitch, last 15 mm from the tip', 'Ø 1.5–2 mm, 6–7 mm pitch, last 25 mm from the tip', 'Ø 1–1.2 mm, 3–4 mm pitch, last 40 mm from the tip', 'Ø 2.5–3 mm, 8–9 mm pitch, last 50 mm from the tip'], answer: 1, explain: 'Ø 1.5–2 mm at 6–7 mm pitch, with the last hole about 25 mm from the tip.' },
  ],

  'sm-unlined': [
    { q: 'You are starting an unlined strap with 1.1 mm and 2.2 mm firm veg-tan on the bench. What do you cut?', options: ['The 1.1 mm, with reinforcement added', 'Two layers of the 1.1 mm, glued', 'The 1.1 mm, skived at the tails', 'The 2.2 mm'], answer: 3, explain: 'One heavier layer replaces the laminate, so cut from 2.0–2.4 mm (5–6 oz) firm veg-tan or Horween.' },
    { q: 'Your pieces are bevelled, punched, oiled and dyed. What comes next?', options: ['Finish the edges while the piece is flat', 'Skive the tails and fold them over', 'Glue the tails round the hardware', 'Punch the stitch holes with the chisel'], answer: 0, explain: 'Wet-sand at 400 and burnish now. Folded and stitched zones are hard to burnish later.' },
    { q: 'An unlined strap has no lining against the wrist. What do you do about the flesh side?', options: ['Leave it raw so that it can breathe', 'Sand it, add gum or Tokonole and burnish', 'Coat it with edge paint and heat-set it', 'Cover it with a thin sheet of Velodon'], answer: 1, explain: 'The flesh side becomes the wrist face. Sand it 400–600, skive off stringy fibres, apply gum tragacanth or Tokonole and burnish it smooth.' },
    { q: 'You are stitching across the glued joint of an unlined strap. How do you make it hold?', options: ['Sew with a doubled thread', 'Add a rivet through the joint', 'Pass each hole three times', 'Stop the seam short of the joint'], answer: 2, explain: 'Start mid-seam and pass each hole three times across the joint. Stitch the edges too.' },
    { q: 'You are folding a tail round its hardware. How do you glue it?', options: ['Coat it all first, then pass it round in one go', 'Glue the channel first, then the tip last', 'Glue the tip, pass it round, then work away', 'Glue towards the hardware, finishing at the bar'], answer: 2, explain: 'Glue the first 3.2 mm or so of the tail tip and pass it round the hardware grain-side out. Then glue the rest of the overlap, working away from the hardware, and clamp.' },
  ],

  'sm-remborde': [
    { q: 'The finished strap will be 20 mm wide. How wide do you cut the core?', options: ['About 22 mm', 'About 20 mm', 'About 18 mm', 'About 14 mm'], answer: 2, explain: 'The core is about 1 mm per side narrower than the finished strap, so about 18 mm. The top’s skived margin wraps round it.' },
    { q: 'You are skiving the turn margin on a chrome calf top. Which skive suits it?', options: ['A step skive, a uniform band of about 0.6 mm', 'A step skive, a uniform band of about 1.5 mm', 'A long taper to paper-thin', 'No skive, only a groove on the fold line'], answer: 0, explain: 'A step skive leaves a uniform band of about 0.6 mm and is good on chrome calf. A long taper to paper-thin suits firm leather.' },
    { q: 'You reach for PVA to cement the turned margin. What should you use?', options: ['PVA is fine, clamped until it dries', 'Superglue, along the fold line', 'Neoprene or water-based contact cement', 'Gum tragacanth, worked into the margin'], answer: 2, explain: 'Cement the margins and the underside edge of the core with neoprene or water-based contact cement, and wait for tack. PVA barely holds until dry.' },
    { q: 'You are finishing a semi-rembordé strap. How do you deal with the lining at the edge?', options: ['Trim it inside the fold so it hides', 'Trim it flush and paint the junction', 'Leave it proud and burnish it with gum', 'Wrap it round the edge of the top'], answer: 1, explain: 'In semi-rembordé the lining closes the bottom, so trim it flush and paint the junction, its weak point. Trimming just inside the fold is the full rembordé finish.' },
    { q: 'A calf margin will have to turn round the tip curve. What do you plan before skiving?', options: ['Dampen the whole margin', 'Widen the turn allowance at the tip', 'Cut small V-notches round the curve', 'Leave the tip for a painted edge'], answer: 2, explain: 'Cut small V-notches (crans) round the tip curve at regular intervals before skiving, or plan to pleat it.' },
  ],

  'sm-padded': [
    { q: 'A padded strap is 20 mm wide at the lug end. How wide is the filler there?', options: ['22 mm', '20 mm', '16–18 mm', '10–14 mm'], answer: 3, explain: 'The filler is inset 3–5 mm per side, so 20 mm less 6–10 mm leaves 10–14 mm. The flat flange that remains carries the stitching.' },
    { q: 'A padded lug fold comes out too bulky to fit the case. What is the likely cause?', options: ['The filler runs into the fold', 'The flanges were left unglued at first', 'The dome was carved too narrow', 'The lining was laid with a slight stretch'], answer: 0, explain: 'The filler is never in a fold. It stops short, so the lug fold forms beyond its end and the doubled fold can still equal one layer.' },
    { q: 'You are pricking a domed strap. Where do the holes go?', options: ['Through the dome, close to the centre', 'Through the flange and the filler edge', 'Through the flange only', 'Through the lining only'], answer: 2, explain: 'Prick and stitch through the flange only, top and lining, never the dome. Paper between iron and dome stops it marking.' },
    { q: 'Your padded strap has a veg-tan top, a foam filler and a calf lining. Which edge do you plan?', options: ['Burnished, cut slightly oversize', 'Painted, cut slightly undersize', 'Burnished, cut slightly undersize', 'Painted, cut slightly oversize'], answer: 1, explain: 'Burnish only if every layer is veg-tan, so this stack gets paint. Paint adds width, so the strap is cut slightly undersize.' },
    { q: 'You are punching the adjustment holes on a padded long piece. Where does the first one go?', options: ['Past the end of the filler', 'On the flange, beside the seam', 'Under the end of the dome', 'Through the thickest part of the filler'], answer: 0, explain: 'Holes start where the filler ends. On the long piece the filler stops 5 mm before the first hole.' },
  ],

  'sm-rally': [
    { q: 'You want a contrasting lining to show through the openings. When do you punch them?', options: ['Through both layers, after laminating', 'In the top only, before assembly', 'In the lining only, before assembly', 'Through both layers, before gluing'], answer: 1, explain: 'For the underlay look, punch the top only before assembly so the lining shows through. Punching both layers after laminating gives the see-through look.' },
    { q: 'Your punches don’t match the measured opening sizes exactly. What do you do?', options: ['Order punches to the exact measured size', 'Open each hole with a knife until it matches', 'Use one size only, and drop the small holes', 'Use the nearest punches and keep that pairing'], answer: 3, explain: 'No maker publishes opening diameters. The sizes are measured from commercial straps, so choose the nearest punches you own and keep that pairing as your house standard.' },
    { q: 'Your layout leaves only 1 mm of leather between an opening and the stitch line. What do you do?', options: ['Stitch closer to the edge to win room', 'Keep it, because the lining supports it', 'Move the stitch line further in', 'Let the seam run through the opening'], answer: 0, explain: 'Keep at least 1.5 mm of leather between any opening and the stitch line. Racing straps often stitch at about 2 mm from the edge to win that room.' },
    { q: 'You are adding a little padding under a rally top. Where does it go?', options: ['Under the openings, for a softer feel', 'Across the full length of the strap', 'Into the lug fold, to fill it out', 'Outside the opening zones'], answer: 3, explain: 'Keep any padding outside the opening zones.' },
    { q: 'You have finished the opening block on the long piece. What goes on the short piece?', options: ['A block of smaller holes', 'An identical block of openings', 'A plain face, with no openings', 'A block in a second layout'], answer: 1, explain: 'Put an identical block on both pieces. On the short piece the keepers sit below it.' },
  ],

  'sm-pilot': [
    { q: 'You scale a pilot pattern to a 22 mm strap using this lesson’s 1.3 × proportion. About how far below the fold does full width run?', options: ['About 17 mm', 'About 22 mm', 'About 29 mm', 'About 44 mm'], answer: 2, explain: '1.3 × 22 mm is about 29 mm. The proportion comes from one maker’s published schematic, so cut the pattern in card and try it first.' },
    { q: 'A customer wants a pilot strap with a turned edge all the way round. What do you tell them?', options: ['It works if the corners are well softened', 'The square tail needs a cut, painted edge', 'It works over a narrower core at the tail', 'The square tail needs a burnished edge'], answer: 1, explain: 'A pilot tail can’t be turned (rembordé), so it takes a cut, painted edge.' },
    { q: 'You want the two classic flieger rivets. Where do they go?', options: ['Beyond the end of the fold’s tail', 'In the lug fold, to lock it shut', 'On the fold spine, one each side', 'Through the bar channel itself'], answer: 0, explain: 'Set them beyond the end of the fold’s tail and never in the flex zone (Rule 3). Many pilot straps leave them off.' },
    { q: 'Your seam kinks where it goes round the concave shoulder. How do you prick it next time?', options: ['Carry the long iron straight through the shoulder', 'Open the shoulder holes by eye with an awl', 'Stop the seam at the shoulder and restart below it', 'Walk it with the 2-prong iron, keyed in the last hole'], answer: 3, explain: 'Walk the concave curve with the 2-prong iron, keying one prong in the last hole as on the tip, so the seam follows the shoulder without a kink.' },
  ],

  'sm-bund': [
    { q: 'The case measures 42 mm with the crown, the pad will sit under the crown, and the lug width is 20 mm. How do you draw the pad?', options: ['Centre 20 mm wide, ends 42 mm wide', 'Centre 42 mm wide, ends 20 mm wide', 'Centre 42 mm wide, ends 25 mm wide', 'Centre 25 mm wide, ends 42 mm wide'], answer: 2, explain: 'The waisted outline has a centre width equal to the case diameter and ends of lug width plus 5 mm: 20 + 5 = 25 mm.' },
    { q: 'A customer wants a Bund with a heavily padded strap. What do you advise?', options: ['A thin strap, because padded ones jam', 'Padded is fine with wider passages', 'Padded is fine with a 110 mm pad', 'Padded is fine on a single-layer pad'], answer: 0, explain: 'Heavily padded straps jam in the passages. Use an unpadded two-piece strap of about 2.2 mm, or a single-pass strip.' },
    { q: 'You are copying a vintage slip-through pad. About how long do you draw it?', options: ['40–50 mm', '100–110 mm', '120–130 mm', '66–73 mm'], answer: 3, explain: 'Vintage-pattern slip-through pads run 66–73 mm. Modern pads are longer, at 100–110 mm.' },
    { q: 'The pad and strap are both finished. How do you assemble them?', options: ['Thread the pad first, then fit the bars', 'Fit the strap to the bars, then thread the pad', 'Glue the pad to the caseback, then add the strap', 'Stitch the pad to the strap, then fit the bars'], answer: 1, explain: 'Fit the strap to the bars, then thread it through the pad so the pad sits under the caseback.' },
  ],

  'sm-singlepass': [
    { q: 'You have a 2.4 mm veg-tan strip for a single-pass strap. What do you do?', options: ['Use it as it is, because thicker is stronger', 'Skive only the fold ends and keep the body', 'Add a thin lining for comfort under the case', 'Split it down to about 1.3–1.6 mm first'], answer: 3, explain: 'The strip passes over both bars, so the clearance there caps its thickness. Cut from 4–5 oz or split to 1.3–1.6 mm.' },
    { q: 'You want to rivet the buckle loop shut. What is the limit?', options: ['No rivets on veg-tan at all', 'Rivets only in pairs across the lugs', 'Keep rivets clear of the lugs', 'Rivets only with a second flap'], answer: 2, explain: 'Stitch the loop, or glue and rivet it, but keep rivets away from the lugs, where the strap flexes.' },
    { q: 'On the wrist, the tail passes through only one keeper. What is the target?', options: ['At least two keepers', 'One is enough on a Zulu strap', 'Three keepers, evenly spaced', 'No keepers, with the tail tucked'], answer: 0, explain: 'Fit one or two floating leather keepers on the build. The tail should pass at least two.' },
    { q: 'You are fitting a finished strap. Which threading path is right?', options: ['Under the top bar, over the case, under the bottom bar', 'Over the top bar, under the case, over the bottom bar', 'Over the top bar, over the case, over the bottom bar', 'Under the top bar, under the case, under the bottom bar'], answer: 1, explain: 'Over the top bar, under the case, over the bottom bar, then through the buckle and keepers, tucking the surplus tail.' },
  ],

  'sm-nosew': [
    { q: 'A customer wants to swap the buckle later without cutting anything. Which joint do you use?', options: ['Mini rivets', 'A glued fold', 'A glued fold backed by rivets', 'Chicago screws'], answer: 3, explain: 'Chicago screws are removable. Accept their size, about 9 mm across and 6 mm tall at the smallest, and use threadlocker, because they loosen without it.' },
    { q: 'You choose glue-and-fold for its flat, fast joint. What is the catch?', options: ['It is rigid and permanent', 'It peels under flex and sweat', 'It loosens without threadlocker', 'It stands about 6 mm tall'], answer: 1, explain: 'Glue-and-fold is flattest and fastest but peels under flex and sweat unless backed up. Rivets are the rigid, permanent joint, and Chicago screws are the tall ones that loosen.' },
    { q: 'You are placing rivets on a no-sew strap. Which plan is right?', options: ['Off the flex zones, and the bar keeps its own loop', 'In the fold, so they lock the bar channel', 'Along the fold spine, 12.7 mm apart', 'Through the channel, in place of the bar’s loop'], answer: 0, explain: 'Rivets are strong in shear but permanent and rigid, so keep them off flex zones. The bar still needs its own loop.' },
    { q: 'You are folding a strip over the hardware. Where does the glue go?', options: ['Over the whole strip, channel included', 'Inside the channel, to grip the bar', 'On the tab tip and its landing zone', 'On the grain side of the fold'], answer: 2, explain: 'Glue only the tab tip and its landing zone, fold over the hardware once tacky, and leave the channel unglued.' },
  ],

  'sm-minimal': [
    { q: 'You plan a stitchless strap in a soft, spongy, oiled leather. What do you do?', options: ['Keep it and add extra coats of edge paint', 'Change to a firm, dense top', 'Keep it and leave off the lining', 'Keep it and add a padded filler'], answer: 1, explain: 'The glue carries the load. Soft, spongy, heavily oiled or padded leathers peel at the edge without a seam, so use a firm, dense top such as shell or firm veg-tan.' },
    { q: 'A tack-stitched strap is laminated and cured. What comes before any stitching?', options: ['Wrap the cord round the corners', 'Sew the V at the tip', 'Cut to the outline and paint the edges', 'Punch the holes and fit the keepers'], answer: 2, explain: 'Cut and paint before any stitching. There is no seam to work round, and the paint is part of what holds the edge.' },
    { q: 'A client asks you to leave the lining out of a stitchless strap to save thickness. What do you say?', options: ['Fine, because glue alone holds the top', 'Fine, if the top is at least 2.5 mm thick', 'Fine, if the edges get extra paint', 'Keep it, or the strap goes floppy'], answer: 3, explain: 'All three minimal versions keep the lining. It is what stops a seamless strap going floppy.' },
    { q: 'Your firm top is Minerva Box, an oiled leather. What does it need before gluing?', options: ['A good scuff on the flesh', 'A wipe of neatsfoot oil on the flesh', 'A damp sponge on the grain', 'A warm iron on the grain'], answer: 0, explain: 'Minerva Box is oiled, so scuff its flesh well for the glue. On a minimal-stitch strap the glue carries the load.' },
    { q: 'You are building a stitchless strap. Where does it still get stitches?', options: ['At the lug end', 'At the tip', 'Round the fixed keeper', 'Along both long edges'], answer: 2, explain: 'A stitchless strap has none at the lug at all. Glue and paint carry it, with two stitches round the fixed keeper.' },
  ],

  'sm-qr': [
    { q: 'You are cutting the notch on a lined strap. What does it pass through?', options: ['The back layer of the loop only', 'Every layer, top face included', 'The top face only', 'The lining, the tail and the top'], answer: 0, explain: 'The notch goes through the back (underside) layer of the loop only, which on a lined strap is the returning tail. The top face stays uncut.' },
    { q: 'The knob is hard to reach through the notch. What do you do?', options: ['Cut the notch through the top as well', 'Change to a stiffer leather round it', 'Fit a longer quick-release bar', 'Skive the back layer thin at the notch'], answer: 3, explain: 'Stiff, thick leather round the notch makes the knob hard to reach. Skive that layer thin there so the knob is easy to reach.' },
    { q: 'Your edges still need their final finishing. When do you mark the knob position?', options: ['After the final coats, with the bar removed', 'Now, with the bar inserted', 'Now, by measuring in from the tip', 'Once the strap is on the watch'], answer: 1, explain: 'Before final edge finishing, insert the bar and mark the knob on the underside.' },
    { q: 'Your planned fold seam runs where the notch will go. What do you change?', options: ['Move the notch onto the top face', 'Stitch through the notch to close it', 'Move the seam further from the bar', 'Make the notch shorter than the knob'], answer: 2, explain: 'Stitch or rivet far enough from the bar that the notch misses the seam.' },
    { q: 'You have just cut the notch. What do you do to its edges?', options: ['Leave them raw so the knob slides', 'Glue them shut round the knob', 'Stretch them over the bar', 'Paint or seal them'], answer: 3, explain: 'Paint or seal the cut edges of the notch.' },
  ],

  'sm-smartwatch': [
    { q: 'A customer brings a 45 mm Apple Watch and an adapter. What sets your strap’s lug width?', options: ['The case size in a maker’s table', 'The width of the buckle', 'Calipers on the adapter’s strap slot', 'The width of the customer’s old band'], answer: 2, explain: 'The strap’s lug width is the adapter’s strap slot. Case-size tables only guide you: calipers on the slot decide.' },
    { q: 'The customer wants to be able to swap this strap onto another adapter later. Which adapter do you build for?', options: ['A spring-bar adapter', 'A fixed adapter', 'A fixed adapter with a notch', 'A fixed adapter, glued only'], answer: 0, explain: 'A spring-bar adapter has its own spring bar, so the strap is built like any lug strap and can be swapped. A strap folded round a fixed adapter is never separated from it.' },
    { q: 'You are building on a fixed adapter. What do you do before wrapping the top round the bar?', options: ['Run the side seams', 'Paint the lug-end edge', 'Cut a notch for the knob', 'Glue the lining round the bar'], answer: 1, explain: 'Paint the lug-end edge first, because you can’t reach it later. The lining stops short of the fold.' },
    { q: 'Your sample fold won’t enter the adapter slot. What do you do?', options: ['Cut the top anyway, as leather compresses', 'Tap it in with a mallet to seat it', 'File the slot wider to take the fold', 'Thin the fold and test another sample'], answer: 3, explain: 'The fold has to enter the slot. That is why you glue a sample fold and push it into the adapter before you cut the real top.' },
    { q: 'You are drafting for a 24 mm slot. Which taper does this lesson give?', options: ['24 → 22', '24 → 18', '24 → 20', '24 → 14'], answer: 1, explain: 'Smartwatch straps taper harder than a watch strap: 20 → 16, 22 → 18, 24 → 18, 26 → 20.' },
  ],

  'sm-exotic': [
    { q: 'You are finishing the edge of an alligator strap. Which route do you rule out?', options: ['Painting', 'Binding', 'Burnishing', 'Turning'], answer: 2, explain: 'Reptile is chrome-tanned, so paint, bind or turn the edge, and never burnish. Expect paint to dry unevenly.' },
    { q: 'An alligator strap looks dry. What do you apply?', options: ['A thin coat of neatsfoot oil', 'A beeswax-heavy wax', 'A solvent polish', 'A reptile cream or lanolin'], answer: 3, explain: 'Use a dedicated reptile cream such as Saphir Reptan, or lanolin. Oil leaves white water-stain spots on alligator, and a beeswax-heavy wax cracks off.' },
    { q: 'You are pricking alligator and a hole is about to land on the soft skin between tiles. What do you do?', options: ['Shift it so that it sits in a tile', 'Punch it, then seal it with glue', 'Use a larger hole so it won’t tear', 'Pull that stitch tighter than the rest'], answer: 0, explain: 'Adjust for hard tiles and soft inter-tile fibre by keeping holes off the soft seams. At layout, keep that soft skin off the stitch line too.' },
    { q: 'You are thinning an alligator skin. What is the danger in skiving from the back?', options: ['The tiles flatten and lose their shine', 'It cuts through the low spots', 'The skin turns stiff at the folds', 'Calcium deposits rise through the tiles'], answer: 1, explain: 'Skive mainly the folds and edges, because skiving from the back can cut through the low spots between tiles. Or order the skin pre-thinned.' },
    { q: 'You need shell cordovan for a strap. How do you buy and work it?', options: ['Buy it thick, then split it down at the bench', 'Buy it thick, then skive it along its length', 'Buy it near final thickness, then polish with solvent', 'Buy it near final thickness, then skive folds lightly'], answer: 3, explain: 'Shell is only 1–2 mm thick and variable, and splitting is delicate. Buy near final thickness, skive only the folds lightly and use cordovan-safe products: solvent polishes swell its fibres.' },
  ],

  'sm-fit': [
    { q: 'Wrinkles run across the top of a strap you made. What do you do on the next one?', options: ['Use a smaller bevel', 'Condition it less often', 'Boat the long lining', 'Cut along the backbone'], answer: 2, explain: 'The lining was glued flat and the strap bent afterwards (Rule 2). Next time, boat the long lining so the laminate is born curved.' },
    { q: 'Edge paint has cracked at the fold. What do you change?', options: ['A small bevel, thin coats, and stop at the fold', 'A big bevel, so the paint has more to grip', 'One thick coat, run over the fold spine', 'A burnish with Tokonole under the paint'], answer: 0, explain: 'Too big a bevel, too thick a coat or paint on the fold spine causes it (Rule 3). Use a small bevel and thin coats, and stop at the fold.' },
    { q: 'A strap’s holes have stretched toward the buckle within weeks. Which cause fits?', options: ['No reinforcement, or belly leather', 'Over-conditioning the lining', 'A lining glued on flat', 'Too much edge paint'], answer: 0, explain: 'Stretched holes come from no reinforcement, belly leather or a strap cut across the grain. Reinforce the body and cut along the backbone.' },
    { q: 'On the wearer’s wrist the pin sits in hole 1 of 7, and no standard length helps. What do you change?', options: ['The number of holes', 'The strap lengths', 'The spacing of the keepers', 'The taper of the strap'], answer: 1, explain: 'One maker’s target is the pin in hole 3, 4 or 5 of 7. If no standard length gets you there, change the lengths, not the number of holes.' },
    { q: 'A new firm strap feels stiff in its first few days. What do you do?', options: ['Warm it with a hairdryer', 'Dampen it and bend it round a bottle', 'Keep wearing it for a week or two', 'Condition it every day until it softens'], answer: 2, explain: 'A firm strap softens over a week or two as it takes your wrist’s curve. Don’t force it with heat or water.' },
  ],
}
